ALTER TABLE #GUIAS_ARTESANOS_ANALISIS_SOLICITADO_PAOLA_GUERRERO ADD  CONSTRAINT [ZZZZIDX_GUIAS_SOLICITADO_PAOLA_GUERRERO] UNIQUE NONCLUSTERED 
(
NUMERO_GUIA	ASC
)
WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, SORT_IN_TEMPDB = OFF, IGNORE_DUP_KEY = OFF, ONLINE = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, FILLFACTOR = 80) ON [PRIMARY]


DELETE #GUIAS_ARTESANOS_ANALISIS_SOLICITADO_PAOLA_GUERRERO WHERE FECHA_ENVIO < '2025-11-30' OR FECHA_ENVIO IS NULL



--select * from #GUIAS_ARTESANOS_ANALISIS_SOLICITADO_PAOLA_GUERRERO


/*
SELECT NUMERO_GUIA,COUNT(1) FROM #GUIAS_ARTESANOS_ANALISIS_SOLICITADO_PAOLA_GUERRERO WHERE FECHA_ENVIO >='2025-11-01'
GROUP BY NUMERO_GUIA
HAVING COUNT(1)>1
*/

DROP TABLE IF EXISTS #SEGUIMIENTO_ENVIO_ARTESANOS_ANALISIS_SOLICITADO_PAOLA_GUERRERO;
SELECT SEG.* 
INTO #SEGUIMIENTO_ENVIO_ARTESANOS_ANALISIS_SOLICITADO_PAOLA_GUERRERO
FROM #GUIAS_ARTESANOS_ANALISIS_SOLICITADO_PAOLA_GUERRERO GUI
INNER JOIN Mece_Logistico..SEGUIMIENTO_ENVIO SEG WITH(NOLOCK)
ON SEG.NUMERO_GUIA=GUI.NUMERO_GUIA


DROP TABLE IF EXISTS #GUIAS_ULT_PRIM_SOLICITADO_PAOLA_GUERRERO;
;WITH CTE AS(
SELECT 
ROW_NUMBER() OVER(PARTITION BY TMP.NUMERO_GUIA ORDER BY TMP.FECHA_HORA_MOVIMIENTO DESC) AS ROW_ID_ULTMOV,
ROW_NUMBER() OVER(PARTITION BY TMP.NUMERO_GUIA ORDER BY TMP.FECHA_HORA_MOVIMIENTO ASC)  AS ROW_ID_PRIMMOV,
TMP.NUMERO_GUIA,
G.FECHA_ENVIO,
G.NOMBRE_REMITE_GUIA,
G.APELLIDO_REMITE_GUIA,
G.VALOR_DECLARADO_GUIA,
G.VALOR_DESCUENTO_GUIAS,
G.VALOR_FLETES_GUIAS,
G.VALOR_FLETES_GUIAS_FACT,
G.VALOR_SEG_MAN_GUIAS,
G.VALOR_SEG_MAN_GUIAS_FACT,
PROD.NOMBRE_PRODUCTO,
PR.ID_PROCESO,
PR.NOMBRE_PROCESO_LOG,
TMP.FECHA_HORA_MOVIMIENTO
FROM #SEGUIMIENTO_ENVIO_ARTESANOS_ANALISIS_SOLICITADO_PAOLA_GUERRERO TMP 
INNER JOIN #GUIAS_ARTESANOS_ANALISIS_SOLICITADO_PAOLA_GUERRERO G
ON G.NUMERO_GUIA=TMP.NUMERO_GUIA
INNER JOIN PARAMETROS..PROCESOS PR WITH(NOLOCK)
ON PR.ID_PROCESO=TMP.ID_PROCESO
INNER JOIN PARAMETROS..PRODUCTOS PROD WITH(NOLOCK)
ON PROD.ID_PRODUCTO=G.ID_PRODUCTO
)SELECT * 
INTO #GUIAS_ULT_PRIM_SOLICITADO_PAOLA_GUERRERO
FROM CTE WHERE 
	ROW_ID_ULTMOV=1
OR ROW_ID_PRIMMOV=1

DROP TABLE IF EXISTS #GUIAS_TABLA_FINAL;
SELECT TMP.NUMERO_GUIA
INTO #GUIAS_TABLA_FINAL
FROM #SEGUIMIENTO_ENVIO_ARTESANOS_ANALISIS_SOLICITADO_PAOLA_GUERRERO TMP 
INNER JOIN #GUIAS_ARTESANOS_ANALISIS_SOLICITADO_PAOLA_GUERRERO G
ON G.NUMERO_GUIA=TMP.NUMERO_GUIA
GROUP BY TMP.NUMERO_GUIA


--SELECT * FROM #GUIAS_ULT_PRIM_SOLICITADO_PAOLA_GUERRERO

SELECT 
 T_GUIAS.NUMERO_GUIA	
,PRIM_MOV.FECHA_ENVIO	
,PRIM_MOV.NOMBRE_PRODUCTO	
,PRIM_MOV.NOMBRE_PROCESO_LOG AS NOMBRE_PROCESO_LOG_PRIMER_MOV	
,PRIM_MOV.FECHA_HORA_MOVIMIENTO AS FECHA_HORA_MOVIMIENTO_PRIMER_MOV
,ULT_MOV.NOMBRE_PROCESO_LOG AS NOMBRE_PROCESO_LOG_ULT_MOV	
,ULT_MOV.FECHA_HORA_MOVIMIENTO AS FECHA_HORA_MOVIMIENTO_ULT_MOV
,PRIM_MOV.NOMBRE_REMITE_GUIA	
,PRIM_MOV.APELLIDO_REMITE_GUIA	
,PRIM_MOV.VALOR_DECLARADO_GUIA	
,PRIM_MOV.VALOR_DESCUENTO_GUIAS	
,PRIM_MOV.VALOR_FLETES_GUIAS	
,PRIM_MOV.VALOR_FLETES_GUIAS_FACT	
,PRIM_MOV.VALOR_SEG_MAN_GUIAS	
,PRIM_MOV.VALOR_SEG_MAN_GUIAS_FACT	
FROM #GUIAS_TABLA_FINAL T_GUIAS
INNER JOIN #GUIAS_ULT_PRIM_SOLICITADO_PAOLA_GUERRERO PRIM_MOV
ON T_GUIAS.NUMERO_GUIA=PRIM_MOV.NUMERO_GUIA AND PRIM_MOV.ROW_ID_PRIMMOV=1
INNER JOIN #GUIAS_ULT_PRIM_SOLICITADO_PAOLA_GUERRERO ULT_MOV
ON T_GUIAS.NUMERO_GUIA=ULT_MOV.NUMERO_GUIA AND ULT_MOV.ROW_ID_ULTMOV=1
--WHERE T_GUIAS.NUMERO_GUIA=399758993



--SELECT * FROM #GUIAS_ULT_PRIM_SOLICITADO_PAOLA_GUERRERO PRIM_MOV
--WHERE NUMERO_GUIA=399758993
